440	// ========== WebSocket Connection Handling ==========
441	
442	const clients = new Set();
443	
444	function handleUpgrade(req, socket) {
445	  if (!isAuthorized(req) || !isAllowedWebSocketOrigin(req)) { socket.destroy(); return; }
446	
447	  const key = req.headers['sec-websocket-key'];
448	  if (!key) { socket.destroy(); return; }
449	
450	  const accept = computeAcceptKey(key);
451	  socket.write(
452	    'HTTP/1.1 101 Switching Protocols\r\n' +
453	    'Upgrade: websocket\r\n' +
454	    'Connection: Upgrade\r\n' +
455	    'Sec-WebSocket-Accept: ' + accept + '\r\n\r\n'
456	  );
457	
458	  let buffer = Buffer.alloc(0);
459	  clients.add(socket);
460	
461	  socket.on('data', (chunk) => {
462	    buffer = Buffer.concat([buffer, chunk]);
463	    while (buffer.length > 0) {
464	      let result;
465	      try {
466	        result = decodeFrame(buffer);
467	      } catch (e) {
468	        socket.end(encodeFrame(OPCODES.CLOSE, Buffer.alloc(0)));
469	        clients.delete(socket);
470	        return;
471	      }
472	      if (!result) break;
473	      buffer = buffer.slice(result.bytesConsumed);
474	
475	      switch (result.opcode) {
476	        case OPCODES.TEXT:
477	          handleMessage(result.payload.toString());
478	          break;
479	        case OPCODES.CLOSE:
480	          socket.end(encodeFrame(OPCODES.CLOSE, Buffer.alloc(0)));
481	          clients.delete(socket);
482	          return;
483	        case OPCODES.PING:
484	          socket.write(encodeFrame(OPCODES.PONG, result.payload));
485	          break;
486	        case OPCODES.PONG:
487	          break;
488	        default: {
489	          const closeBuf = Buffer.alloc(2);
490	          closeBuf.writeUInt16BE(1003);
491	          socket.end(encodeFrame(OPCODES.CLOSE, closeBuf));
492	          clients.delete(socket);
493	          return;
494	        }
495	      }
496	    }
497	  });
498	
499	  socket.on('close', () => clients.delete(socket));
500	  socket.on('error', () => clients.delete(socket));
501	}
502	
503	function handleMessage(text) {
504	  let event;
505	  try {
506	    event = JSON.parse(text);
507	  } catch (e) {
508	    console.error('Failed to parse WebSocket message:', e.message);
509	    return;
510	  }
511	  touchActivity();
512	  console.log(JSON.stringify({ source: 'user-event', ...event }));
513	  if (event && event.choice) {
514	    const eventsFile = path.join(STATE_DIR, 'events');
515	    fs.appendFileSync(eventsFile, JSON.stringify(event) + '\n');
516	  }
517	}
518	
519	function broadcast(msg) {
520	  const frame = encodeFrame(OPCODES.TEXT, Buffer.from(JSON.stringify(msg)));
521	  for (const socket of clients) {
522	    try { socket.write(frame); } catch (e) { clients.delete(socket); }
523	  }
524	}
