526	// Best-effort: open the user's browser the first time a screen is actually ready
527	// to show. Skips when disabled, on a non-loopback (remote) bind, or when a
528	// browser is already connected. Override the launcher with BRAINSTORM_OPEN_CMD.
529	let browserOpened = false;
530	function maybeOpenBrowser() {
531	  if (browserOpened) return;
532	  browserOpened = true;
533	  if (!process.env.BRAINSTORM_OPEN) return; // opt-in: only after the user approves the companion
534	  if (HOST !== '127.0.0.1' && HOST !== 'localhost') return;
535	  if (clients.size > 0) return; // the user already opened it
536	  const url = companionUrl(); // must carry the key or the gate 403s it
537	  const cp = require('child_process');
538	  // Operator-provided launcher: run as given (this env var is trusted operator input).
539	  if (process.env.BRAINSTORM_OPEN_CMD) {
540	    try { cp.exec(process.env.BRAINSTORM_OPEN_CMD + ' ' + JSON.stringify(url), () => {}); } catch (e) { /* best effort */ }
541	    return;
542	  }
543	  // Platform launchers: pass the URL as an argv element via execFile (no shell),
544	  // so a url-host containing shell metacharacters can't inject a command.
545	  const launcher = browserLauncherForPlatform(url);
546	  if (!launcher) return; // headless: nothing to open
547	  try { cp.execFile(launcher.bin, launcher.args, () => {}); } catch (e) { /* best effort */ }
548	}
549	
550	// ========== Activity Tracking ==========
551	
552	// Idle timeout: shut down after this long with no activity. Default 4 hours;
553	// override with BRAINSTORM_IDLE_TIMEOUT_MS (start-server.sh: --idle-timeout-minutes).
554	const IDLE_TIMEOUT_MS = (() => {
555	  const ms = Number(process.env.BRAINSTORM_IDLE_TIMEOUT_MS);
556	  return Number.isFinite(ms) && ms > 0 ? ms : 4 * 60 * 60 * 1000;
557	})();
558	// How often the watchdog checks for owner-death / idleness. Configurable mainly
559	// so tests can run fast; production default is 60s.
560	const LIFECYCLE_CHECK_MS = (() => {
561	  const ms = Number(process.env.BRAINSTORM_LIFECYCLE_CHECK_MS);
562	  return Number.isFinite(ms) && ms > 0 ? ms : 60 * 1000;
563	})();
564	let lastActivity = Date.now();
565	
566	function touchActivity() {
567	  lastActivity = Date.now();
568	}
569	
570	// ========== File Watching ==========
571	
572	const debounceTimers = new Map();
573	
574	// ========== Server Startup ==========
575	
576	function startServer() {
577	  if (!fs.existsSync(CONTENT_DIR)) fs.mkdirSync(CONTENT_DIR, { recursive: true });
578	  if (!fs.existsSync(STATE_DIR)) fs.mkdirSync(STATE_DIR, { recursive: true });
579	
580	  // Track known files to distinguish new screens from updates.
581	  // macOS fs.watch reports 'rename' for both new files and overwrites,
582	  // so we can't rely on eventType alone.
583	  const knownFiles = new Set(
584	    fs.readdirSync(CONTENT_DIR).filter(f => !f.startsWith('.') && f.endsWith('.html'))
585	  );
586	
587	  const server = http.createServer(handleRequest);
588	  server.on('upgrade', handleUpgrade);
589	
590	  const watcher = fs.watch(CONTENT_DIR, (eventType, filename) => {
591	    if (!filename || filename.startsWith('.') || !filename.endsWith('.html')) return;
592	
593	    if (debounceTimers.has(filename)) clearTimeout(debounceTimers.get(filename));
594	    debounceTimers.set(filename, setTimeout(() => {
595	      debounceTimers.delete(filename);
596	      const filePath = path.join(CONTENT_DIR, filename);
597	
598	      if (!fs.existsSync(filePath)) return; // file was deleted
599	      touchActivity();
600	
601	      if (!knownFiles.has(filename)) {
602	        knownFiles.add(filename);
603	        const eventsFile = path.join(STATE_DIR, 'events');
604	        if (fs.existsSync(eventsFile)) fs.unlinkSync(eventsFile);
605	        console.log(JSON.stringify({ type: 'screen-added', file: filePath }));
606	        maybeOpenBrowser();
607	      } else {
608	        console.log(JSON.stringify({ type: 'screen-updated', file: filePath }));
609	      }
610	
611	      broadcast({ type: 'reload' });
612	    }, 100));
613	  });
614	  watcher.on('error', (err) => console.error('fs.watch error:', err.message));
615	
616	  function shutdown(reason) {
617	    console.log(JSON.stringify({ type: 'server-stopped', reason }));
618	    const infoFile = path.join(STATE_DIR, 'server-info');
619	    if (fs.existsSync(infoFile)) fs.unlinkSync(infoFile);
620	    fs.writeFileSync(
621	      path.join(STATE_DIR, 'server-stopped'),
622	      JSON.stringify({ reason, timestamp: Date.now() }) + '\n'
623	    );
624	    watcher.close();
625	    clearInterval(lifecycleCheck);
626	    // Close any upgraded WebSocket sockets so server.close() can complete and
627	    // the process actually exits instead of lingering on an open connection.
628	    for (const socket of clients) {
629	      try { socket.destroy(); } catch (e) { /* already gone */ }
630	    }
631	    server.close(() => process.exit(0));
632	  }
633	
634	  function ownerAlive() {
635	    if (!ownerPid) return true;
636	    try { process.kill(ownerPid, 0); return true; } catch (e) { return e.code === 'EPERM'; }
637	  }
638	
639	  // Periodically exit if the owner process died or we've been idle too long.
640	  const lifecycleCheck = setInterval(() => {
641	    if (!ownerAlive()) shutdown('owner process exited');
642	    else if (Date.now() - lastActivity > IDLE_TIMEOUT_MS) shutdown('idle timeout');
643	  }, LIFECYCLE_CHECK_MS);
644	  lifecycleCheck.unref();
645	
646	  // Validate owner PID at startup. If it's already dead, the PID resolution
647	  // was wrong (common on WSL, Tailscale SSH, and cross-user scenarios).
648	  // Disable monitoring and rely on the idle timeout instead.
649	  if (ownerPid) {
650	    try { process.kill(ownerPid, 0); }
651	    catch (e) {
652	      if (e.code !== 'EPERM') {
653	        console.log(JSON.stringify({ type: 'owner-pid-invalid', pid: ownerPid, reason: 'dead at startup' }));
654	        ownerPid = null;
655	      }
656	    }
657	  }
658	
659	  // If the preferred port is already taken (e.g. a previous server is still
660	  // alive), fall back to a random port once instead of failing.
661	  let triedFallback = false;
662	
663	  function onListen() {
664	    // Cookie name keys on the ACTUAL bound port (may differ from the preferred
665	    // one after an EADDRINUSE fallback) so it can't collide with another server's
666	    // cookie in the shared localhost jar.
667	    COOKIE_NAME = 'brainstorm-key-' + PORT;
668	    // Record the bound port AND token so the next restart of this session reuses
669	    // them — but ONLY when we got our preferred port. On a fallback we bound a
670	    // *different* port because someone else holds the preferred one; persisting
671	    // would overwrite the shared files and strand that other session's open tab.
672	    if (PORT_FILE && !triedFallback) {
673	      try { fs.writeFileSync(PORT_FILE, String(PORT)); } catch (e) { /* best effort */ }
674	      if (TOKEN_FILE) {
675	        try {
676	          fs.writeFileSync(TOKEN_FILE, TOKEN, { mode: 0o600 });
677	          chmodOwnerOnly(TOKEN_FILE);
678	        } catch (e) { /* best effort */ }
679	      }
680	    }
681	    const info = JSON.stringify({
682	      type: 'server-started', port: Number(PORT), host: HOST,
683	      url_host: URL_HOST, url: companionUrl(),
684	      screen_dir: CONTENT_DIR, state_dir: STATE_DIR, idle_timeout_ms: IDLE_TIMEOUT_MS
685	    });
686	    console.log(info);
687	    // server-info embeds the key — keep it owner-only.
688	    fs.writeFileSync(path.join(STATE_DIR, 'server-info'), info + '\n', { mode: 0o600 });
689	  }
690	
691	  server.on('error', (err) => {
692	    if (err.code === 'EADDRINUSE' && !triedFallback) {
693	      if (tokenSource === 'env') {
694	        console.error('Server failed to bind: preferred port is in use and BRAINSTORM_TOKEN is set; refusing fallback with explicit token');
695	        process.exit(1);
696	      }
697	      triedFallback = true;
698	      PORT = randomPort();
699	      if (tokenSource === 'file') {
700	        TOKEN = generateToken();
701	        tokenSource = 'generated-fallback';
702	      }
703	      server.listen(PORT, HOST, onListen);
704	    } else {
705	      console.error('Server failed to bind:', err.message);
706	      process.exit(1);
707	    }
708	  });
709	  server.listen(PORT, HOST, onListen);
710	}
